	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/interchanges", wrapper.IngestFile)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/interchanges/reprocess", wrapper.ReprocessInterchanges)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/interchanges/{id}", wrapper.GetInterchange)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/interchanges/{id}/raw", wrapper.GetRawFile)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/interchanges/{id}/rollback", wrapper.RollbackVersion)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/liveness", wrapper.GetLiveness)
	})
